  var source=AssetDatabase.LoadAssetAtPath<GameObject>(SourcePrefab);Need(source,"Current Island prefab missing");var sourceAnimator=source.GetComponentInChildren<Animator>();var original=sourceAnimator.runtimeAnimatorController as AnimatorController;Need(original&&original.layers.Length==1&&sourceAnimator.avatar&&sourceAnimator.avatar.isHuman,"Expected current single-layer valid own Human target");string originalPath=AssetDatabase.GetAssetPath(original);var sm=original.layers[0].stateMachine;Func<string,AnimatorState> state=n=>sm.states.Single(x=>x.state.name==n).state;Func<string,AnimationClip> clip=n=>state(n).motion as AnimationClip;var guard=clip("Guard");var crouch=clip("Crouch");var back=clip("WalkBack");var uppercut=clip("uppercut");Need(guard&&crouch&&back&&uppercut&&new[]{guard,crouch,back,uppercut}.All(c=>c.humanMotion),"Require actual postHuman source clips");Need(AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(guard))==GuardGUID&&AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(crouch))==CrouchGUID&&AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(back))==BackGUID,"Current source binding identity changed; re-audit before building");
