s.Contains(path)||r<=.01f),"Mask changed nonarm local pose or bone length: "+stateName+" phase "+phase+" "+path+" p="+p+" r="+r+" s="+s);}count++;}Need(allowedMax>5,"Masked source arms did not visibly change any tested arm rotation");File.WriteAllText(folder+"/animator-only-gates.json",JsonUtility.ToJson(new VerifyReport{status="ANIMATOR_ONLY_INVARIANTS_PASSED_RUNTIME_NATIVE_PRECEDENCE_CONTACT_EOF_VISUAL_PENDING",passed=true,samples=count,maxForbiddenLocalPosition=position,maxForbiddenLocalRotationDegrees=rotation,maxForbiddenLocalScale=scale,maxAllowedArmRotationDegrees=allowedMax},true));}
